import{_ as t,o as r,c as e,a8 as s}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"圣玛加利男女英文中小学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-428ec14a","school_zh":"圣玛加利男女英文中小学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"圣玛加利男女英文中小学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-SMC-FIRST","C2223-SMC-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-428ec14a/s1/2022-23-interview.md","filePath":"reports/school-428ec14a/s1/2022-23-interview.md"}'),p={name:"reports/school-428ec14a/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="圣玛加利男女英文中小学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">圣玛加利男女英文中小学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#圣玛加利男女英文中小学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;圣玛加利男女英文中小学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-428ec14a">← 返回圣玛加利男女英文中小学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-smc-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-smc-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-smc-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>分站评估</strong></p><p>不同学生反馈约45分钟至一小时。一个版本登记后到二楼礼堂，家长在小食部等候；四张桌子分别评估中文、英文、数学及日常问答，每站一位老师。以下汇总来自不同学生。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语及普通话，按任务区分</p><p><strong>朗读与短讲</strong></p><p>朗读中文文章或指定一段，部分以普通话朗读并回答理解题；另有一分钟演说“假如回到过去，你会……”。</p><p><strong>阅读与情境问答</strong></p><p>介绍最喜欢的书并接受追问；讲述一次争执；若发现好友偷东西会怎样做；外地朋友来香港会推荐哪些景点。自我介绍可用粤语，老师据此了解想教什么学科、周末亲子活动及阅读。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读、介绍与观点</strong></p><p>朗读文章或指定两段并回答理解题，自我介绍后继续追问。题目包括为何选择圣玛加利、朋友是否重要、对社交媒体的看法。</p></blockquote><blockquote><p><strong>数学：</strong> 部分反馈明确英语，其他未注明</p><p><strong>iPad限时答题</strong></p><p>常见为10分钟10题，也有九题版本；桌面提供纸笔运算。涵盖四则运算、百分率、分数、平均数、方程、速率及因数。</p></blockquote><blockquote><p><strong>个人交流：</strong> 中文；部分含普通话</p><p><strong>校园生活与兴趣</strong></p><p>谈学校生活、趣事、校队、担任的职务、平日喜欢做什么；活动在哪里进行、学习程度如何。老师会从自我介绍延伸提问。</p></blockquote><h2 id="record-c2223-smc-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-smc-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-smc-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>学生与家长分开面见</strong></p><p>多份反馈由副校长或老师分别面见学生及家长。一个版本学生约10至15分钟、家长另约10至15分钟；学校也会与家长交流首轮表现。</p></blockquote><blockquote><p><strong>学生面谈：</strong> 中文为部分反馈明确；其余未注明</p><p><strong>学习与目标</strong></p><p>自我介绍、目标、需要改善之处、领导才能、平日如何学习，如何兼顾学业和运动，以及参加哪些课外活动。</p><p><strong>家庭与日常生活</strong></p><p>圣诞假期去了哪里、回家后做什么、想当什么科目的老师及原因，是否经常见父亲和沟通。另有较多假设情境问题，具体题目随交流变化。</p><p><strong>择校与提问</strong></p><p>还面试了哪些直资或津贴学校、若同时录取会选择哪间、为什么选择圣玛加利，以及有什么问题想问学校。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 中文为部分反馈明确；其余未注明</p><p><strong>了解孩子与家庭支持</strong></p><p>形容孩子、优点及待改善之处、怎样相处与管教、谁跟进功课、是否补习、周末亲子活动、怎样支持学业与运动平衡。会问孩子英文能否适应、是否认同学习外语，以及家长对未来的期望。</p><p><strong>学习表现与择校</strong></p><p>讨论成绩表操行、老师曾否解释评分；了解课外活动、为何选校、对学校的认识，以及希望学校帮助孩子什么。家长也有提问机会。</p></blockquote><blockquote><p><strong>家长反馈：</strong></p><p><strong>首轮表现回顾</strong></p><p>有家长表示，校方会肯定孩子答得好的地方，也讨论未能回答的题目。家长从交流中留意到朗读准确性、停顿、感情和表达均获关注；对于假设题，则感受到学校重视思考方法及表达。这是家长对面谈的观察。</p></blockquote>',22)])])}const u=t(p,[["render",n]]);export{h as __pageData,u as default};
